Translate("ptBR", "lorax", {
	title = "Lorax",
	subtitle = "Sátiro da Forja Demoníaca",
	found = "Ruínas no sul da Garganta dos Sussurros Gelados",
	hint = [=[Procure o sátiro que anda de um lado para outro entre ruínas na garganta do sul.]=],
	allegiance = "Nenhuma",
	sections = {
		{
			title = "Resumo",
			text = [=[Lorax é um {link:satyrs}sátiro{/link} que fica entre ruínas no sul de {link:winterspring}Hibérnia{/link}. Segundo suas próprias palavras, seus dias giram num lento círculo de pesar, ódio e tramas. Ele conhece a arte da forja demoníaca. Certa vez fez um trato para ensiná-la a um {link:orcs}orc{/link} {link:blackrock-mountain}Rocha Negra{/link} chamado Goraluk Anvilcrack, em troca de sua alma. Goraluk levou um peitoral ainda não forjado e fugiu para o Pico da Rocha Negra sem pagar.]=],
		},
		{
			title = "Feitos",
			text = [=[• Ele oferece seu conhecimento a quem cobrar a alma que lhe devem.
• Ele entrega uma lança imbuída de energia vil para beber a alma de Goraluk quando ele morrer.]=],
		},
	},
	chapters = {
		{
			title = "O Trato Quebrado",
			hint = "Ouça a história do sátiro e acerte sua dívida.",
			text = [=[Uma alma, qualquer alma, vale alguma coisa nestes tempos, disse Lorax, até a de um {link:orcs}orc{/link} {link:blackrock-mountain}Rocha Negra{/link}. Quando a lança voltou manchada com a alma de Goraluk, e com ela o peitoral roubado, o {link:satyrs}sátiro{/link} cumpriu sua parte do pacto.]=],
		},
	},
	mentions = {
		{ text = "A História de Lorax" },
		{ text = "A Forja Demoníaca" },
	},
})

