Translate("ptBR", "winterfall-furbolgs", {
	title = "Pelursos Invernosos",
	aliases = { "Invernosos", "tribo Invernosa" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Invernosos são a tribo de {link:furbolgs}pelursos{/link} de {link:winterspring}Hibérnia{/link}. Não eram um povo violento, e por muito tempo foram aliados dos {link:timbermaw-furbolgs}Presamatos{/link}. Isso mudou. Seu chefe supremo lhes fez exigências estranhas, e agora eles caem sobre qualquer um que se aproxime, fera ou viajante, elfo ou goblin. Mantêm uma aldeia nas colinas a leste de {link:everlook}Visteterna{/link} e acampamentos perto das {link:frostfire-hot-springs}Fontes Termais de Fogofrio{/link}.]=],
		},
		{
			title = "A Aguardente",
			text = [=[A loucura tem uma origem. Mensageiros da tribo atravessam o {link:timbermaw-hold}Domínio dos Presamatos{/link} até os pelursos {link:deadwood-furbolgs}Lenha Morta{/link} da {link:felwood}Selva Maleva{/link}, eles próprios enlouquecidos pela corrupção vil. Trazem de volta uma bebida verde feita do veneno dos horrores tóxicos da {link:irontree-woods}Floresta Ferrárbol{/link}. Pura, ela os mataria. Misturada à água das fontes termais, perde o poder de matar, mas mantém sua força, e os que a bebem ficam maiores e mais selvagens. É por isso que os Invernosos guardam as fontes com tanta ferocidade. Os pelursos ainda carregam contas espirituais para afastar os maus espíritos, mas as contas não os salvaram daquilo em que se tornaram.]=],
		},
	},
})

Translate("ptBR", "crystal-of-zin-malor", {
	title = "Cristal de Zin-Malor",
	sections = {
		{
			title = "Resumo",
			text = [=[O Cristal de Zin-Malor é uma relíquia capaz de conter e comandar grandes forças arcanas. Só os verdadeiramente dignos podem dominá-lo, e só um punhado dos magos mais fortes poderia ter essa esperança. Ele leva o nome do {link:temple-of-zin-malor}Templo de Zin-Malor{/link}, que hoje jaz em ruínas em {link:azshara}Azshara{/link}. Em tempos antigos, os Bem-nascidos de {link:lake-kel-theril}Kel'Theril{/link} o roubaram, pretendendo drenar seu poder para si. Na tentativa, o cristal se despedaçou numa grande explosão, e seus pedaços afundaram sob o gelo do lago. Os Bem-nascidos foram amaldiçoados a permanecer ali para sempre, ainda em busca dos fragmentos.]=],
		},
		{
			title = "Refeito",
			text = [=[Nos dias atuais, a picareta de um {link:dwarves}anão{/link} rompeu o gelo e trouxe à tona quatro fragmentos. A alta elfa {link:aurora-skycaller}Aurora Skycaller{/link} os reconheceu. Com os escritos sagrados dos Bem-nascidos, recuperados do templo arruinado em {link:azshara}Azshara{/link}, ela refez o cristal inteiro. Ele foi mostrado a um espírito de {link:lake-kel-theril}Kel'Theril{/link} que se arrependia do antigo crime, e esse espírito encontrou paz. O cristal jamais poderia voltar ao seu templo. {link:wynd-nightchaser}Wynd Nightchaser{/link}, de {link:starfall-village}Chuva Estelar{/link}, o enviou ao {link:fandral-staghelm}Arquidruida Fandral Staghelm{/link}, em {link:darnassus}Darnassus{/link}, que elogiou os que o carregaram por não tentarem usá-lo eles mesmos.]=],
		},
	},
})
